<?php
require_once __DIR__.'/../includes/bootstrap.php'; require_role('commercial_manager');
$user=current_user();$flashes=render_flashes();$currentPage='saved_searches';$pageTitle='Saved Searches';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$managerId=(int)($user['id']??$user['user_id']??0);
$rows=[];if(cm_table($conn,'commercial_saved_searches')){$s=$conn->prepare("SELECT id,search_name,source_search_reference,taxonomy_version,result_count,data_snapshot_at,created_at FROM commercial_saved_searches WHERE commercial_manager_id=? ORDER BY created_at DESC");$s->bind_param('i',$managerId);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();}
require __DIR__.'/_layout_start.php';?>
<div class="cm-page-header"><div><span>Source Reconciliation</span><h2>Saved Searches</h2><p>Every capability pack reconciles to a preserved search snapshot.</p></div></div>
<div class="cm-card"><div class="cm-card__header"><div><h3>Search Snapshots</h3><p><?= count($rows) ?> saved search(es).</p></div></div><?php if(!$rows):?><div class="cm-empty"><i class="fas fa-bookmark"></i><strong>No saved searches</strong><span>Create or import a saved-search snapshot first.</span></div><?php else:?><div class="cm-table-wrap"><table><thead><tr><th>Name</th><th>Source</th><th>Taxonomy</th><th>Results</th><th>Snapshot</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?= e($r['search_name']) ?></strong></td><td><?= e($r['source_search_reference']?:'—') ?></td><td><?= e($r['taxonomy_version']) ?></td><td><?= number_format((int)$r['result_count']) ?></td><td><?= e(cm_datetime($r['data_snapshot_at'])) ?><span><?= e(cm_currency($r['data_snapshot_at'])) ?></span></td><td><a class="cm-icon-btn" href="<?= url('commercial_manager/saved_search_view.php?id='.(int)$r['id']) ?>"><i class="fas fa-arrow-right"></i></a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div>
<?php require __DIR__.'/_layout_end.php';?>